episode_fence_v1124:
"""v1.10.24 跨来源集级完成栅栏。

解决“某一集已经由迅雷秒传成功，后续光鸭分享/Magnet/ED2K 又把同一集再存一次”的竞态：
- 成功集号一旦进入 media_facts，立即成为所有来源共享的终态事实；
- 缺集计算、pending reservation、光鸭分享文件筛选都实时扣除终态集；
- Magnet/ED2K 在 create/retry 前重新读取当前缺集，已覆盖任务直接停止，部分重叠任务先取消旧 task 再按剩余集重建；
- 同一订阅的迅雷/分享主流程与外部云添加提交共用一把媒体级锁，避免两个来源同时越过缺集门禁。

这里的“停止”是集级而不是整部剧级：E04 成功后只封死 E04，E05/E06 仍可继续由后续来源补齐。
"""

from __future__ import annotations

import threading
from typing import Any, Dict, Iterable, List, Set, Tuple

from .episode_resolver_v190 import AUTO_SELECT_CONFIDENCE, reliable_episode_set, resolve_episode
from .legacy import _is_subtitle, _is_video


_ACTIVE_OFFLINE_STATES_V1124 = {"new", "retry", "dispatching", "submitted", "queued", "waiting"}
_PENDING_SHARE_STATES_V1124 = {"planned", "submitted", "task_confirmed", "verifying"}


def _safe_int_v1124_fence(value: Any, default: int = 0) -> int:
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return default


class GuangYaEpisodeFenceV1124Mixin:
    """所有获取来源共用的“成功一集即封死一集”最终门禁。"""

    build_id = "20260903-r40"

    def init_plugin(self, config: dict = None) -> None:
        self._episode_fence_guard_v1124 = threading.Lock()
        self._episode_fence_locks_v1124: Dict[str, threading.RLock] = {}
        return super().init_plugin(config)

    def _episode_fence_lock_v1124(self, subscribe: Any) -> threading.RLock:
        key = self._media_fact_prefix(subscribe)
        guard = getattr(self, "_episode_fence_guard_v1124", None)
        locks = getattr(self, "_episode_fence_locks_v1124", None)
        if guard is None or locks is None:
            self._episode_fence_guard_v1124 = threading.Lock()
            self._episode_fence_locks_v1124 = {}
            guard = self._episode_fence_guard_v1124
            locks = self._episode_fence_locks_v1124
        with guard:
            lock = locks.get(key)
            if lock is None:
                lock = threading.RLock()
                locks[key] = lock
            return lock

    _LIBRARY_OBSERVATION_ORIGINS_V1124 = frozenset({
        "library", "emby", "mediaserver", "scan", "media_library", "library_observation",
    })

    @classmethod
    def _is_library_observation_origin_v1124(cls, origin: Any) -> bool:
        text = str(origin or "").strip().lower()
        if not text:
            return False
        if text in cls._LIBRARY_OBSERVATION_ORIGINS_V1124:
            return True
        return any(token in text for token in ("library", "emby", "mediaserver", "scan"))

    @classmethod
    def _is_transfer_receipt_origin_v1124(cls, origin: Any) -> bool:
        """Only real transfer/remote origins count as transfer-acquired."""
        if cls._is_library_observation_origin_v1124(origin):
            return False
        text = str(origin or "").strip().lower()
        if not text:
            return False
        markers = (
            "guangya", "xunlei", "magnet", "ed2k", "offline", "transfer",
            "receipt", "remote", "cloud", "viewing", "flash", "share",
        )
        return any(token in text for token in markers)

    def _acquired_episode_facts_v1124(self, subscribe: Any) -> Set[int]:
        """Transfer receipts only — library observation must never become acquired."""
        if not subscribe or self._is_movie_subscription(subscribe):
            return set()
        prefix = self._media_fact_prefix(subscribe) + ":e"
        facts = self.get_data("media_facts") or {}
        acquired: Set[int] = set()
        if not isinstance(facts, dict):
            return acquired
        for key, row in facts.items():
            text = str(key or "")
            if not text.startswith(prefix):
                continue
            suffix = text[len(prefix):]
            if not (suffix.isdigit() and int(suffix) > 0):
                continue
            origin = ""
            if isinstance(row, dict):
                origin = str(row.get("origin") or "")
            # Legacy keys without origin: treat as transfer only if not explicitly library.
            if origin and self._is_library_observation_origin_v1124(origin):
                continue
            if origin and not self._is_transfer_receipt_origin_v1124(origin):
                continue
            if not origin:
                # Ambiguous pre-r95 rows without origin — do not treat as permanent acquired.
                continue
            acquired.add(int(suffix))
        return acquired

    def _subscription_missing_episodes(self, subscribe: Any) -> List[int]:
        """即使 SubscribeOper/note 暂时未刷新，也绝不把成功回执集重新视为缺集。"""
        parent_missing = {
            _safe_int_v1124_fence(value)
            for value in (super()._subscription_missing_episodes(subscribe) or [])
            if _safe_int_v1124_fence(value) > 0
        }
        return sorted(parent_missing - self._acquired_episode_facts_v1124(subscribe))

    def _pending_reservations(self, subscribe: Any, exclude_job_key: str = "") -> Dict[str, Any]:
        """In-flight jobs only — transfer receipts are NOT reservations."""
        base = dict(super()._pending_reservations(subscribe, exclude_job_key=exclude_job_key) or {})
        base["paths"] = set(base.get("paths") or set())
        base["episodes"] = set(base.get("episodes") or set())
        if self._is_movie_subscription(subscribe):
            try:
                base["movie"] = bool(base.get("movie")) or bool(self._movie_transfer_confirmed(subscribe))
            except Exception:
                base["movie"] = bool(base.get("movie"))
        # Do NOT union acquired episode facts into reservations.
        return base

    @staticmethod
    def _planned_path_v1124(item: Dict[str, Any]) -> str:
        return str(
            item.get("effective_path")
            or item.get("relative_path")
            or item.get("path")
            or item.get("name")
            or ""
        ).replace("\\", "/").strip()

    def _resolved_item_episodes_v1124(
        self,
        subscribe: Any,
        item: Dict[str, Any],
        package_paths: Iterable[str],
    ) -> Set[int]:
        path = self._planned_path_v1124(item)
        if not path or not (_is_video(path) or _is_subtitle(path)):
            return set()
        result = resolve_episode(
            path,
            package_paths=list(package_paths or []),
            season_hint=getattr(subscribe, "season", None),
        )
        threshold = float(getattr(self, "_episode_auto_confidence", AUTO_SELECT_CONFIDENCE) or AUTO_SELECT_CONFIDENCE)
        return set(reliable_episode_set(result, threshold))

    def _filter_inflight_planned_items(
        self,
        subscribe: Any,
        planned: List[Dict[str, Any]],
        exclude_job_key: str = "",
    ) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
        """光鸭分享最终提交前再次按成功集号裁剪；多集文件与成功集重叠时整体拒绝。"""
        ready, held = super()._filter_inflight_planned_items(
            subscribe,
            planned,
            exclude_job_key=exclude_job_key,
        )
        if not ready:
            return ready, held
        if self._is_movie_subscription(subscribe):
            if bool(self._pending_reservations(subscribe, exclude_job_key=exclude_job_key).get("movie")):
                blocked = [item for item in ready if _is_video(self._planned_path_v1124(item)) or _is_subtitle(self._planned_path_v1124(item))]
                keep = [item for item in ready if item not in blocked]
                return keep, [*held, *blocked]
            return ready, held

        acquired = self._acquired_episode_facts_v1124(subscribe)
        if not acquired:
            return ready, held
        package_paths = [self._planned_path_v1124(item) for item in ready if self._planned_path_v1124(item)]
        keep: List[Dict[str, Any]] = []
        blocked: List[Dict[str, Any]] = []
        blocked_episodes: Set[int] = set()
        for item in ready:
            episodes = self._resolved_item_episodes_v1124(subscribe, item, package_paths)
            overlap = episodes.intersection(acquired)
            if overlap:
                blocked.append(item)
                blocked_episodes.update(overlap)
            else:
                keep.append(item)
        if blocked:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【集级终止】#%s 光鸭分享提交前拦截 %s 个重复文件；已成功集=%s",
                int(getattr(subscribe, "id", 0) or 0),
                len(blocked),
                ",".join(f"E{value:02d}" for value in sorted(blocked_episodes)),
            )
        return keep, [*held, *blocked]

    @staticmethod
    def _source_episode_targets_v1124(source: Dict[str, Any]) -> Set[int]:
        values: Set[int] = set()
        for field in ("resolved_episodes", "target_episodes"):
            for raw in source.get(field) or []:
                value = _safe_int_v1124_fence(raw)
                if value > 0:
                    values.add(value)
        return values

    def _delete_offline_task_v1124(self, source: Dict[str, Any]) -> bool:
        task_id = str(source.get("task_id") or "").strip()
        if not task_id:
            return True
        try:
            response = self._offline_request(
                "/cloudcollection/v2/delete_task",
                {"taskIds": [task_id]},
            )
            return bool(self._offline_api_success(response))
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【集级终止】取消重复云添加 task=%s 失败：%s",
                task_id,
                str(err)[:260],
            )
            return False

    def _disable_offline_source_v1124(
        self,
        source: Dict[str, Any],
        acquired: Set[int],
        *,
        reason: str,
    ) -> Dict[str, Any]:
        source_id = str(source.get("id") or "")
        state = str(source.get("state") or "")
        remote_cancelled = True
        if str(source.get("task_id") or "").strip() and state in _ACTIVE_OFFLINE_STATES_V1124:
            remote_cancelled = self._delete_offline_task_v1124(source)
        updated = self._update_source(
            source_id,
            state="disabled",
            enabled=False,
            auto_dispatch=False,
            superseded_by_receipt=True,
            superseded_episodes=sorted(acquired),
            superseded_at=self._now_text(),
            superseded_reason=str(reason)[:400],
            remote_cancelled=bool(remote_cancelled),
            next_retry_at=0,
        ) or source
        self._plugin_log(
            "INFO" if remote_cancelled else "WARNING",
            "【光鸭转存助手】【集级终止】来源 %s 已停止：%s；服务端任务取消=%s",
            source_id or "-",
            reason,
            remote_cancelled,
        )
        return updated

    def _supersede_offline_sources_v1124(self, subscribe: Any, acquired: Set[int]) -> int:
        if not acquired:
            return 0
        sid = int(getattr(subscribe, "id", 0) or 0)
        store_method = getattr(self, "_source_store", None)
        if sid <= 0 or not callable(store_method):
            return 0
        try:
            items = dict((store_method().get("items") or {}))
        except Exception:
            return 0
        stopped = 0
        for source in items.values():
            if not isinstance(source, dict) or int(source.get("subscribe_id") or 0) != sid:
                continue
            state = str(source.get("state") or "")
            if state not in _ACTIVE_OFFLINE_STATES_V1124:
                continue
            targets = self._source_episode_targets_v1124(source)
            if not targets:
                continue
            remaining = targets - acquired
            if not remaining:
                self._disable_offline_source_v1124(
                    source,
                    acquired,
                    reason="目标集已被其它成功来源确认获得",
                )
                stopped += 1
                continue
            # 尚未创建服务端任务时可以安全把目标缩小到真正剩余的集数。
            if remaining != targets and not str(source.get("task_id") or "").strip() and state in {"new", "retry"}:
                self._update_source(
                    str(source.get("id") or ""),
                    target_episodes=sorted(remaining),
                    superseded_episodes=sorted(targets.intersection(acquired)),
                    superseded_at=self._now_text(),
                )
        return stopped

    def _supersede_share_jobs_v1124(self, subscribe: Any, acquired: Set[int]) -> int:
        """旧的待确认分享任务若全部集数都已被成功回执覆盖，则不再重放。"""
        if not acquired:
            return 0
        prefix = self._media_fact_prefix(subscribe)
        jobs = self.get_data("transfer_jobs") or {}
        if not isinstance(jobs, dict):
            return 0
        changed = 0
        for key, raw in list(jobs.items()):
            if not isinstance(raw, dict):
                continue
            if str(raw.get("media") or "") != prefix or str(raw.get("status") or "") not in _PENDING_SHARE_STATES_V1124:
                continue
            paths = [str(value or "") for value in (raw.get("paths") or []) if str(value or "").strip()]
            if not paths:
                continue
            episodes: Set[int] = set()
            for path in paths:
                episodes.update(self._resolved_item_episodes_v1124(subscribe, {"path": path}, paths))
            if not episodes or not episodes.issubset(acquired):
                continue
            row = dict(raw)
            row["status"] = "superseded"
            row["superseded_episodes"] = sorted(episodes)
            row["superseded_at"] = self._now_text()
            row["cancel_reason"] = "这些集已由其它来源成功存入，旧待确认任务不再重放"
            jobs[key] = row
            changed += 1
        if changed:
            self.save_data("transfer_jobs", jobs)
        return changed

    def _commit_episode_receipt_v1124(self, subscribe: Any, episodes: Iterable[int], origin: str) -> None:
        values = {
            _safe_int_v1124_fence(value)
            for value in episodes
            if _safe_int_v1124_fence(value) > 0
        }
        if not values or self._is_movie_subscription(subscribe):
            return
        sid = int(getattr(subscribe, "id", 0) or 0)
        fresh = self._find_subscription(sid) if sid else None
        current = fresh or subscribe
        # 先把 media_facts 立即回写 MoviePilot note/lack，再以同一事实终止其它来源。
        try:
            self._sync_media_facts_progress(current)
        except Exception as err:
            self._plugin_log("WARNING", "【光鸭转存助手】【集级终止】#%s 回写订阅进度失败：%s", sid, str(err)[:260])
        acquired = self._acquired_episode_facts_v1124(current)
        stopped_sources = self._supersede_offline_sources_v1124(current, acquired)
        stopped_jobs = self._supersede_share_jobs_v1124(current, acquired)
        missing = self._subscription_missing_episodes(current)
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【集级终止】#%s 成功回执=%s origin=%s；订阅已完成集立即增加，剩余=%s；停止重复来源=%s/旧任务=%s",
            sid,
            ",".join(f"E{value:02d}" for value in sorted(values)),
            origin,
            ",".join(f"E{value:02d}" for value in missing) or "无",
            stopped_sources,
            stopped_jobs,
        )
        if not missing:
            try:
                self._finish_subscription_if_complete(current)
            except Exception:
                pass

    def _remember_episode_facts(self, subscribe: Any, episodes: Iterable[int], origin: str = "library") -> int:
        values = sorted({
            _safe_int_v1124_fence(value)
            for value in episodes
            if _safe_int_v1124_fence(value) > 0
        })
        # Library observation must never enter transfer receipt / 集级终止 / missing recalc.
        if self._is_library_observation_origin_v1124(origin):
            return 0
        changed = super()._remember_episode_facts(subscribe, values, origin=origin)
        if values and not self._is_movie_subscription(subscribe) and self._is_transfer_receipt_origin_v1124(origin):
            self._commit_episode_receipt_v1124(subscribe, values, origin)
        return changed

    def _remember_media_facts(self, subscribe: Any, items: List[Dict[str, Any]], origin: str = "transfer") -> int:
        """光鸭直接分享成功也统一转换成高置信集级回执，而不是只记文件路径。"""
        changed = super()._remember_media_facts(subscribe, items, origin=origin)
        if not items or self._is_movie_subscription(subscribe):
            return changed
        package_paths = [self._planned_path_v1124(item) for item in items if self._planned_path_v1124(item)]
        episodes: Set[int] = set()
        for item in items:
            if not _is_video(self._planned_path_v1124(item)):
                continue
            episodes.update(self._resolved_item_episodes_v1124(subscribe, item, package_paths))
        if episodes:
            self._remember_episode_facts(subscribe, episodes, origin=f"{origin}_receipt")
        return changed

    def _prepare_offline_source_v1124(self, source: Dict[str, Any], subscribe: Any) -> Tuple[bool, Dict[str, Any], str]:
        """create/retry 前最后一次按当前缺集裁剪，防止旧计划把成功集再次提交。"""
        source_id = str(source.get("id") or "")
        targets = self._source_episode_targets_v1124(source)
        if self._is_movie_subscription(subscribe):
            try:
                if self._movie_transfer_confirmed(subscribe):
                    updated = self._disable_offline_source_v1124(source, set(), reason="电影正片已经成功获得")
                    return False, updated, "电影已完成，停止重复云添加"
            except Exception:
                pass
            return True, source, ""
        if not targets:
            return True, source, ""

        missing = set(self._subscription_missing_episodes(subscribe))
        remaining = targets.intersection(missing)
        acquired = targets - remaining
        if not remaining:
            updated = self._disable_offline_source_v1124(
                source,
                self._acquired_episode_facts_v1124(subscribe),
                reason="该来源目标集均已成功获得",
            )
            return False, updated, "目标集已完成，停止重复云添加"
        if remaining == targets:
            return True, source, ""

        task_id = str(source.get("task_id") or "").strip()
        if task_id:
            # 已经创建的 cloudcollection 任务无法安全改 fileIndexes：先取消旧任务，再重建剩余集。
            if not self._delete_offline_task_v1124(source):
                updated = self._disable_offline_source_v1124(
                    source,
                    self._acquired_episode_facts_v1124(subscribe),
                    reason="旧任务包含已完成集且无法安全裁剪，宁可停止等待其它来源，也不重复入库",
                )
                return False, updated, "旧任务无法裁剪，已停止以避免重复"
            source = self._update_source(
                source_id,
                state="new",
                task_id="",
                task_status=0,
                progress=0,
                target_episodes=sorted(remaining),
                selected_indexes=[],
                next_retry_at=0,
                superseded_episodes=sorted(acquired),
                superseded_at=self._now_text(),
            ) or source
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【集级终止】来源 %s 旧云添加任务已取消；仅按剩余 %s 重新解析提交",
                source_id,
                ",".join(f"E{value:02d}" for value in sorted(remaining)),
            )
            return True, source, ""

        source = self._update_source(
            source_id,
            target_episodes=sorted(remaining),
            superseded_episodes=sorted(acquired),
            superseded_at=self._now_text(),
        ) or source
        return True, source, ""

    def _submit_offline_source(self, source_id: str) -> Dict[str, Any]:
        source_id = str(source_id or "").strip()
        store = self._source_store()
        source = dict((store.get("items") or {}).get(source_id) or {})
        if not source:
            return {"success": False, "message": "来源不存在"}
        subscribe = self._find_subscription(int(source.get("subscribe_id") or 0))
        if not subscribe:
            return super()._submit_offline_source(source_id)
        lock = self._episode_fence_lock_v1124(subscribe)
        with lock:
            latest = dict((self._source_store().get("items") or {}).get(source_id) or source)
            fresh = self._find_subscription(int(latest.get("subscribe_id") or 0)) or subscribe
            allowed, prepared, message = self._prepare_offline_source_v1124(latest, fresh)
            if not allowed:
                return {"success": True, "handled": True, "message": message, "data": prepared}
            return super()._submit_offline_source(source_id)

    def _poll_offline_source(self, source: Dict[str, Any]) -> Dict[str, Any]:
        source_id = str(source.get("id") or "")
        latest = dict((self._source_store().get("items") or {}).get(source_id) or source)
        subscribe = self._find_subscription(int(latest.get("subscribe_id") or 0))
        if not subscribe:
            return super()._poll_offline_source(latest)
        lock = self._episode_fence_lock_v1124(subscribe)
        with lock:
            latest = dict((self._source_store().get("items") or {}).get(source_id) or latest)
            fresh = self._find_subscription(int(latest.get("subscribe_id") or 0)) or subscribe
            allowed, prepared, message = self._prepare_offline_source_v1124(latest, fresh)
            if not allowed:
                return {"success": True, "handled": True, "message": message, "data": prepared}
            return super()._poll_offline_source(latest)

    def _try_transfer_subscription_inner(
        self,
        subscribe: Any,
        force: bool = False,
        refresh_channel: bool = True,
    ) -> Dict[str, Any]:
        """同一媒体的迅雷→分享→Magnet/ED2K 规划串行通过同一缺集栅栏。"""
        sid = int(getattr(subscribe, "id", 0) or 0)
        current = self._find_subscription(sid) if sid else None
        current = current or subscribe
        lock = self._episode_fence_lock_v1124(current)
        with lock:
            if not self._is_movie_subscription(current):
                try:
                    self._sync_media_facts_progress(current)
                except Exception:
                    pass
            result = super()._try_transfer_subscription_inner(
                current,
                force=force,
                refresh_channel=refresh_channel,
            )
            fresh = self._find_subscription(sid) if sid else None
            if fresh and not self._is_movie_subscription(fresh):
                try:
                    self._sync_media_facts_progress(fresh)
                except Exception:
                    pass
            return result


__all__ = ["GuangYaEpisodeFenceV1124Mixin"]

episode_resolver_v190:
"""v1.9.0 统一剧集识别器。

目标不是“从文件名抓一个数字”，而是把文件名、父目录、整包序列与频道提示一起判断，
给出可解释的 season / episodes / confidence。只有高置信结果才允许自动拆包。
"""

from __future__ import annotations

import re
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple


AUTO_SELECT_CONFIDENCE = 0.90
MAX_EXPLICIT_EPISODE = 9999
_COMMON_NOISE_NUMBERS = {264, 265, 266, 360, 480, 720, 1080, 2160, 4320}
_VIDEO_SUFFIX_RE = re.compile(r"\.[A-Za-z0-9]{2,5}$")
_SEASON_RE = re.compile(r"(?i)(?:^|[^A-Za-z0-9])S(?:eason)?[\s._-]*0*(\d{1,2})(?=[^0-9]|$)")
_X_RE = re.compile(r"(?i)(?:^|[^0-9])0*(\d{1,2})x0*(\d{1,4})(?=[^0-9]|$)")
_EP_RANGE_RE = re.compile(
    r"(?i)(?:^|[^A-Za-z])E(?:P(?:ISODE)?)?[\s._-]*0*(\d{1,4})"
    r"(?:[\s._]*(?:-|~|～|—|至|\+)[\s._]*E?(?:P(?:ISODE)?)?[\s._-]*0*(\d{1,4}))?"
)
_CHINESE_RE = re.compile(r"第\s*0*(\d{1,4})(?:\s*[-~～—至]\s*0*(\d{1,4}))?\s*[集话]")
_SPECIAL_RE = re.compile(
    r"(?i)(?:^|[^A-Za-z0-9])(?:SP|SPECIAL|OVA|OAD)[\s._-]*0*(\d{1,4})(?=[^0-9]|$)"
)
_CHINESE_SPECIAL_RE = re.compile(r"(?:特别篇|番外|特典)\s*0*(\d{1,4})(?=[^0-9]|$)")
_QUALITY_TOKEN = (
    r"(?:4K|8K|2160P?|1080P?|720P?|480P?|UHD|FHD|HD|HDR(?:10\+?)?|DV|DOVI|"
    r"WEB(?:-?DL)?|BLU-?RAY|BDREMUX|REMUX|HEVC|AVC|AV1|H\.?26[45]|X26[45])"
)
_QUALITY_SUFFIX_RE = re.compile(
    rf"(?ix)^\s*0*(\d{{1,4}})\s*[~～丨|｜]\s*[\[【(（]?\s*{_QUALITY_TOKEN}"
    r"(?=$|[\s._\-\[\]【】()（）])"
)
_RELEASE_EP_BEFORE_QUALITY_RE = re.compile(
    rf"(?ix)(?:^|[\s._\-])0*(\d{{1,4}})(?:v\d+)?(?=[\s._\-]+{_QUALITY_TOKEN}(?:$|[\s._\-\[\]【】()（）]))"
)


def _clean_path(value: Any) -> str:
    return str(value or "").replace("\\", "/").strip()


def _basename(value: Any) -> str:
    return _clean_path(value).rsplit("/", 1)[-1]


def _stem(value: Any) -> str:
    return _VIDEO_SUFFIX_RE.sub("", _basename(value)).strip()


def _expand_range(start: int, end: int) -> List[int]:
    if start <= 0 or end < start or end > MAX_EXPLICIT_EPISODE or end - start > 500:
        return []
    return list(range(start, end + 1))


def _season_from_path(path: Any, explicit_hint: Optional[int] = None) -> Optional[int]:
    if explicit_hint is not None:
        try:
            return max(0, int(explicit_hint))
        except (TypeError, ValueError):
            pass
    value = _clean_path(path)
    matches = list(_SEASON_RE.finditer(value))
    if matches:
        return int(matches[-1].group(1))
    return None


def _strict_parse(value: Any, season_hint: Optional[int] = None) -> Optional[Dict[str, Any]]:
    text = _clean_path(value)
    season = _season_from_path(text, season_hint)
    episodes = set()
    reasons: List[str] = []

    x_match = _X_RE.search(text)
    if x_match:
        if season is None:
            season = int(x_match.group(1))
        episodes.add(int(x_match.group(2)))
        reasons.append("1x02")

    for matched in _EP_RANGE_RE.finditer(text):
        start = int(matched.group(1))
        end = int(matched.group(2)) if matched.group(2) else start
        values = _expand_range(start, end)
        if values:
            episodes.update(values)
            reasons.append("E/EP")

    for raw in re.findall(r"(?i)E(?:P(?:ISODE)?)?[\s._-]*0*(\d{1,4})", text):
        value_int = int(raw)
        if 0 < value_int <= MAX_EXPLICIT_EPISODE:
            episodes.add(value_int)
            reasons.append("multi-E")

    for matched in _CHINESE_RE.finditer(text):
        start = int(matched.group(1))
        end = int(matched.group(2)) if matched.group(2) else start
        values = _expand_range(start, end)
        if values:
            episodes.update(values)
            reasons.append("第N集/话")

    if episodes:
        values = sorted(episode for episode in episodes if 0 < episode <= MAX_EXPLICIT_EPISODE)
        absolute = values[0] if season is None and len(values) == 1 and values[0] > 500 else None
        return {
            "season": season,
            "episodes": values,
            "absolute_episode": absolute,
            "confidence": 1.0,
            "reason": "+".join(dict.fromkeys(reasons)) or "explicit",
            "explicit": True,
        }

    special = _SPECIAL_RE.search(text) or _CHINESE_SPECIAL_RE.search(text)
    if special:
        value_int = int(special.group(1))
        if 0 < value_int <= MAX_EXPLICIT_EPISODE:
            return {
                "season": 0,
                "episodes": [value_int],
                "absolute_episode": None,
                "confidence": 1.0,
                "reason": "special",
                "explicit": True,
            }
    return None


def _looks_like_year(value: int) -> bool:
    return 1900 <= int(value) <= 2099


def _valid_weak_number(candidate: int) -> bool:
    return bool(
        0 < int(candidate) <= MAX_EXPLICIT_EPISODE
        and int(candidate) not in _COMMON_NOISE_NUMBERS
        and not _looks_like_year(int(candidate))
    )


def _weak_numeric_candidate(value: Any) -> Optional[Tuple[int, str]]:
    """只返回位置语义明确的弱数字；不会从 1080p/H265/2026 中间硬抓数字。"""
    stem = _stem(value)
    quality = _QUALITY_SUFFIX_RE.search(stem)
    if quality:
        candidate = int(quality.group(1))
        if _valid_weak_number(candidate):
            return candidate, "quality-suffix"

    release_quality = list(_RELEASE_EP_BEFORE_QUALITY_RE.finditer(stem))
    if release_quality:
        candidate = int(release_quality[-1].group(1))
        if _valid_weak_number(candidate):
            return candidate, "release-before-quality"

    patterns: Sequence[Tuple[str, str]] = (
        (r"[\[【(（]\s*0*(\d{1,4})(?:v\d+)?\s*[\]】)）]", "bracket-number"),
        (r"(?:^|[\s._])[-–—][\s._-]*0*(\d{1,4})(?:v\d+)?(?=\s|[._\[(（]|$)", "dash-number"),
        (r"^\s*0*(\d{1,4})(?:v\d+)?$", "bare-number"),
        (r"^\s*0*(\d{1,4})(?:v\d+)?(?=[\s._\-\[(（])", "leading-number"),
        (r"(?:^|[\s._-])0*(\d{1,4})(?:v\d+)?$", "trailing-number"),
    )
    for pattern, reason in patterns:
        matched = re.search(pattern, stem, re.I)
        if not matched:
            continue
        candidate = int(matched.group(1))
        if not _valid_weak_number(candidate):
            continue
        return candidate, reason
    return None


def _package_sequence_numbers(paths: Iterable[Any]) -> List[int]:
    values = []
    seen = set()
    for path in paths or []:
        strict = _strict_parse(path)
        if strict and strict.get("episodes"):
            continue
        weak = _weak_numeric_candidate(path)
        if not weak:
            continue
        candidate = int(weak[0])
        if candidate not in seen:
            seen.add(candidate)
            values.append(candidate)
    return sorted(values)


def _is_coherent_sequence(values: Sequence[int]) -> bool:
    if len(values) < 3:
        return False
    ordered = sorted(set(int(v) for v in values))
    span = ordered[-1] - ordered[0] + 1
    return span <= len(ordered) + 1 and span <= 500


def resolve_episode(
    path: Any,
    *,
    package_paths: Optional[Iterable[Any]] = None,
    season_hint: Optional[int] = None,
    episode_hint: Any = "",
) -> Dict[str, Any]:
    """返回可解释的剧集识别结果；低于阈值只诊断，不自动拆包。"""
    strict = _strict_parse(path, season_hint=season_hint)
    if strict:
        return strict

    weak = _weak_numeric_candidate(path)
    if not weak:
        return {
            "season": _season_from_path(path, season_hint),
            "episodes": [],
            "absolute_episode": None,
            "confidence": 0.0,
            "reason": "unparsed",
            "explicit": False,
        }

    candidate, weak_reason = weak
    season = _season_from_path(path, season_hint)
    confidence = 0.65
    reason = weak_reason

    hinted = _strict_parse(episode_hint, season_hint=season) if episode_hint else None
    if hinted and candidate in set(hinted.get("episodes") or []):
        confidence = max(confidence, 0.96)
        reason += "+episode-hint"
        if season is None:
            season = hinted.get("season")

    package_numbers = _package_sequence_numbers(package_paths or [])
    if candidate in package_numbers and _is_coherent_sequence(package_numbers):
        confidence = max(confidence, 0.92)
        reason += "+package-sequence"

    if season is not None and weak_reason in {
        "bare-number", "leading-number", "trailing-number", "bracket-number", "dash-number",
        "quality-suffix", "release-before-quality",
    }:
        confidence = max(confidence, 0.90)
        reason += "+season-context"

    absolute = candidate if season is None and candidate > 500 else None
    return {
        "season": season,
        "episodes": [candidate],
        "absolute_episode": absolute,
        "confidence": round(confidence, 3),
        "reason": reason,
        "explicit": False,
    }


def reliable_episode_set(result: Dict[str, Any], threshold: float = AUTO_SELECT_CONFIDENCE) -> set[int]:
    try:
        confidence = float(result.get("confidence") or 0.0)
    except (TypeError, ValueError):
        confidence = 0.0
    if confidence < float(threshold):
        return set()
    values = set()
    for raw in result.get("episodes") or []:
        try:
            value = int(raw)
        except (TypeError, ValueError):
            continue
        if 0 < value <= MAX_EXPLICIT_EPISODE:
            values.add(value)
    return values


__all__ = [
    "AUTO_SELECT_CONFIDENCE",
    "MAX_EXPLICIT_EPISODE",
    "resolve_episode",
    "reliable_episode_set",
]

episode_runtime_v211:
"""2.0.11-r95 P0：Episode Runtime Architecture — observation ≠ receipt ≠ reservation.

Breaks Library→Receipt→Missing→Target recursion; migrates polluted library-origin
facts; AiringDue host heartbeat + runtime fallback singleflight; empty-target submit gate.
"""
from __future__ import annotations

import threading
import time
from contextlib import contextmanager
from typing import Any, Dict, Iterable, Iterator, List, Optional, Set, Tuple


_LIBRARY_ORIGINS = frozenset({
    "library", "emby", "mediaserver", "scan", "media_library", "library_observation",
})
_MIGRATION_MARKER = "episode_facts_migration_v211"
_ACTIVE_INFLIGHT_STATES = frozenset({
    "new", "dispatching", "queued", "submitted", "waiting", "verifying",
    "task_confirmed", "retry", "pending", "running",
})
_TLS = threading.local()


def _positive(values: Any) -> Set[int]:
    out: Set[int] = set()
    for raw in values or []:
        try:
            episode = int(raw)
        except (TypeError, ValueError):
            continue
        if episode > 0:
            out.add(episode)
    return out


def _is_library_origin(origin: Any) -> bool:
    text = str(origin or "").strip().lower()
    if not text:
        return False
    if text in _LIBRARY_ORIGINS:
        return True
    return any(token in text for token in ("library", "emby", "mediaserver", "scan"))


def _context_stack() -> List[Dict[str, Any]]:
    stack = getattr(_TLS, "episode_run_contexts", None)
    if not isinstance(stack, list):
        stack = []
        _TLS.episode_run_contexts = stack
    return stack


class GuangYaEpisodeRuntimeV211Mixin:
    """Runtime supervisor + claim lifecycle + migration + empty-target hard gate."""

    _airing_fallback_stale_seconds_v211 = 15 * 60

    def init_plugin(self, config: dict = None) -> None:
        # Runtime structures BEFORE super() so workers cannot race into facts builders.
        self._episode_runtime_ready_v211 = False
        self._airing_due_lock_v211 = threading.RLock()
        self._airing_due_running_v211 = False
        self._airing_due_owner_v211 = ""
        self._airing_due_cycle_v211 = 0
        self._host_airing_heartbeat_v211 = 0.0
        self._episode_snapshot_tls_v211 = threading.local()
        self._airing_cycle_state_v211: Dict[str, Any] = {}
        if hasattr(self, "_library_sync_reuse_v211"):
            try:
                delattr(self, "_library_sync_reuse_v211")
            except Exception:
                self._library_sync_reuse_v211 = None
        super().init_plugin(config=config)
        self._migrate_library_observation_facts_v211_once()
        self._reopen_library_polluted_superseded_sources_v211()
        self._episode_runtime_ready_v211 = True

    def _episode_runtime_is_ready_v211(self) -> bool:
