                    "message": "订阅已无缺集，跳过迅雷外部检索" if not completed else "订阅已完成，跳过迅雷外部检索",
                }
        if not self._external_round_ok_v1114(subscribe):
            return {
                "success": False,
                "handled": False,
                "shares": 0,
                "attempted_files": 0,
                "successful_files": 0,
